if(path==='/api/social/delete'&&method==='POST'){
 if(!csrf()||!access.owner)return json({error:'not_allowed'},403);
 let b;try{b=await body()}catch{return json({error:'invalid_body'},400)}
 if(b.confirm!==meetup.title)return json({error:'confirmation_required',message:'يلزم تأكيد اسم اللقاء للحذف'},400);
 const imageRows=(await env.DB.prepare('SELECT id,object_key FROM lk_meetup_photos WHERE meetup_id=?').bind(id).all()).results;
 const photoIds=imageRows.map(x=>x.id);
 const statements=[];
 for(const x of photoIds){
  statements.push(env.DB.prepare('DELETE FROM lk_photo_reactions WHERE photo_id=?').bind(x));
  statements.push(env.DB.prepare('DELETE FROM lk_photo_comments WHERE photo_id=?').bind(x));
 }
 for(const table of ['lk_meetup_likes','lk_meetup_comments','lk_meetup_members','lk_meetup_photos']){
  statements.push(env.DB.prepare('DELETE FROM '+table+' WHERE meetup_id=?').bind(id));
 }
 statements.push(env.DB.prepare('DELETE FROM lk_meetups WHERE id=? AND owner_id=?').bind(id,u.id));
 await env.DB.batch(statements);
 for(const p of imageRows){try{await env.PHOTOS.delete(p.object_key)}catch(e){console.warn('Orphaned meetup photo object',p.object_key)}}
 return json({ok:true,deleted:true});
}
 if(path==='/api/social/invite-member'&&method==='POST'){
 if(!csrf()||!meetup)return json({error:'not_found'},404);
 if(!access.owner)return json({error:'not_allowed'},403);
 if(meetup.privacy==='private')return json({error:'private_cannot_invite',message:'غيّر خصوصية اللقاء قبل دعوة مشاركين'},400);
 let b;try{b=await body()}catch{return json({error:'invalid_body'},400)}
 const username=String(b.username||'').trim().replace(/^@/,'').toLowerCase();
 if(!/^[a-z][a-z0-9_]{2,31}$/.test(username))return json({error:'invalid_username',message:'أدخل اسم المستخدم بطريقة صحيحة'},400);
 const target=await env.DB.prepare("SELECT id FROM users WHERE username=? AND account_status='active'").bind(username).first();
 if(!target)return json({error:'member_not_found',message:'لم يُعثر على هذا المستخدم'},404);
 if(target.id===u.id)return json({error:'self_invite',message:'أنت منشئ اللقاء بالفعل'},400);
 const count=await env.DB.prepare('SELECT COUNT(*) AS total FROM lk_meetup_members WHERE meetup_id=?').bind(id).first();
 if(count.total>=30)return json({error:'member_limit',message:'وصل اللقاء للحد الأقصى من المشاركين'},400);
 const previous=await env.DB.prepare('SELECT status FROM lk_meetup_members WHERE meetup_id=? AND user_id=?').bind(id,target.id).first();
 if(previous?.status==='accepted')return json({ok:true,existing:true,status:'accepted'});
 if(previous?.status==='pending')return json({ok:true,existing:true,status:'pending'});
 await env.DB.prepare("INSERT INTO lk_meetup_members(meetup_id,user_id,status) VALUES(?,?,'pending') ON CONFLICT(meetup_id,user_id) DO UPDATE SET status='pending'").bind(id,target.id).run();
 if(ctx?.waitUntil)ctx.waitUntil(lkPushUser(env,target.id,{title:'دعوة لقاء جديدة',body:'دُعيت إلى '+meetup.title,type:'invites',url:'/app?tab=meet&meetup='+encodeURIComponent(id),tag:'meetup:'+id}));
 return json({ok:true,status:'pending'});
}
